    correctKey: 'D',
    explanation: '正しい。株式等の譲渡損失は申告分離課税の枠内（配当等）でのみ通算でき、総合課税の所得とは通算できない。\n損益通算できる損失は不動産所得・事業所得・山林所得・譲渡所得（不・事・山・譲）の4つに限られる。ただし不動産所得のうち土地取得の借入金利子部分や、株式・生活に通常必要でない資産の譲渡損失は通算できない。\n【図解】\n★損益通算できる損失＝「不・事・山・譲」\n○不動産所得・事業所得・山林所得・譲渡所得の損失\n×ただし例外（通算不可）\n×不動産所得の損失のうち土地取得の借入金利子部分\n×上場株式等の譲渡損失（申告分離内でのみ通算）\n×生活に通常必要でない資産（別荘・ゴルフ会員権等）の譲渡損失\n×一時所得・雑所得の損失',
