    explanation: '誤り。返還を要する敷金は預り金であり、収入金額に算入しない。\n不動産所得は貸付規模にかかわらず不動産の貸付けによる所得で、事業的規模の判定には5棟10室基準が用いられる。総収入金額には敷金のうち返還を要しない部分が含まれる。\n【図解】\n★不動産所得のポイント\n○不動産所得＝総収入金額−必要経費\n→敷金・保証金のうち返還不要部分→収入に計上\n→返還を要する敷金→収入ではない（預り金）\n⚠事業的規模の判定＝5棟10室基準\n→事業的規模でも所得区分は「不動産所得」のまま\n×土地取得のための借入金利子→損益通算の対象外',
